const jsonData = pm.response.json();
const bookId = jsonData.ID; 
pm.environment.set("book_id",bookId);

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response has Msg property", function () {
    pm.expect(jsonData).to.have.property("Msg");
});

pm.test("Msg is 'successfully added'", function () {
    pm.expect(jsonData.Msg).to.eql("successfully added");
});

pm.test("Content-Type header exists", function () {
    pm.response.to.have.header("Content-Type");
});

pm.test("Content-Type is JSON", function () {
    pm.expect(pm.response.headers.get("Content-Type")).to.include("application/json");
});

pm.test("Response time below 1200ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});

pm.test("Body text contains 'successfully added'", function () {
    pm.expect(pm.response.text()).to.include("successfully added");
});



const schema = {
  "type": "object",
  "properties": {
    "Msg": {
      "type": "string"
    },
    "ID": {
      "type": "string"
    }
  },
  "required": [
    "Msg",
    "ID"
  ]
}

pm.test("Response body is valid JSON", function () 
{
    pm.response.to.have.jsonSchema(schema);
})

